def compute(vars):
    current = vars["v1"]
    prior = vars["v2"]

    if prior == 0:
        return None

    change = current - prior
    change_ratio = (change / prior) * 100

    return {
        "value": change_ratio,
        "trace": {
            "current_value": current,
            "prior_value": prior,
            "change": change,
            "change_ratio": change_ratio,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
